try {
java.io.File file = new  java.io.File("/root/temp/StaticContent/global/ServiceExport/" + fileName);
javax.imageio.stream.ImageInputStream fileSource = javax.imageio.ImageIO.createImageInputStream(file);
Iterator<javax.imageio.ImageReader> readers = javax.imageio.ImageIO.getImageReaders(fileSource);

  if (readers.hasNext()) {

    // pick the first available ImageReader
    javax.imageio.ImageReader reader = readers.next();

    // attach source to the reader
    reader.setInput(fileSource, true);

    // read metadata of first image
    javax.imageio.metadata.IIOMetadata metadata = reader.getImageMetadata(0);

    String[] names = metadata.getMetadataFormatNames();
    int length = names.length;
    for (int i = 0; i < length; i++) {
      System.out.println( "Format name: " + names[ i ] );
      fileMetaData = "Format name: " + names[ i ];
      org.w3c.dom.Node node = metadata.getAsTree(names[i]);
      org.w3c.dom.NamedNodeMap map = node.getAttributes();
      //fileSources = metadata.getAsTree(names[i]).getAttributes().toString();
      if (map != null) {

            // print attribute values
            int maplength = map.getLength();
        	fileSources = maplength;
            for (int j = 0; j < maplength; j++) {
                org.w3c.dom.Node attr = map.item(j);
                fileMetaData = fileMetaData + " " + attr.getNodeName() +
                                 "=\"" + attr.getNodeValue() + "\"";
            }
        }
    }
  }
}
catch (Exception e) {

  e.printStackTrace();
}

